"""One catalog drives the startup screen, importer labels and ROM checklist."""
from pathlib import Path
import json,html
from build_profiles import lua
r=Path(__file__).resolve().parents[1]
rows=json.loads((r/'tools/rom_requirements.json').read_text())
m=json.loads((r/'mod/manifest.json').read_text())
proper={'firered':'FireRed','leafgreen':'LeafGreen'}
used_by={}
for row in rows:
 row['base']['name']='Pokémon '+proper.get(row['game'],row['game'].title())+' (USA / English)'
 for source in row['sources']:
  spec=next(x for x in m['optional_imports'] if x['id']==source.get('import_id', row['game']+'_'+source['language']))
  source['md5']=spec['md5'];source['size']=spec['size']
  used_by.setdefault(spec['id'],[]).append(row['base']['name']+' '+row['base']['version'])
  spec['description']='SHA-1 '+source['sha1']+'; Basis: '+' / '.join(used_by[spec['id']])+'.'
(r/'tools/rom_requirements.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n')
(r/'mod/rom_requirements.lua').write_text('-- Generated by tools/build_rom_list.py. Exact supported identities.\nreturn '+lua(rows)+'\n')
m['name']='Uni-Language Ascendant'
m['games']=[x['game'] for x in rows]
(r/'mod/manifest.json').write_text(json.dumps(m,ensure_ascii=False,indent=2)+'\n')
parts=[]
for row in rows:
 for source in row['sources']:
  parts.append('<tr><th>'+html.escape(row['name'])+'<small>Gen '+str(row['generation'])+' · '+source['language'].upper()+'</small></th>'+''.join('<td><b>'+html.escape(x['name'])+'</b><small>'+html.escape(x['version'])+'</small><code>'+x['sha1']+'</code></td>' for x in [row['base'],source])+'</tr>')
body='''<!doctype html><html lang="de"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ROM-Liste · Uni-Language Ascendant __VERSION__</title>
<style>body{font:16px/1.5 system-ui;background:#0e1927;color:#edf5f8;max-width:1200px;margin:40px auto;padding:0 24px}h1{font-size:36px}p{max-width:850px;color:#bfd0dd}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:18px 12px;border-bottom:1px solid #334455;vertical-align:top}small,code{display:block}small{color:#a9bdca}code{color:#8fe0bc;font-size:13px;overflow-wrap:anywhere}input{background:#233246;border:1px solid #456;color:white;border-radius:8px;padding:12px;font:inherit;width:330px;max-width:90%}aside{padding:20px;background:#233246;border-radius:8px}a{color:#8fe0bc}@media(max-width:700px){table,tbody,tr,td,th{display:block}thead{display:none}tr{padding:14px 0;border-bottom:2px solid #8fe0bc}td,th{border:0;padding:8px}}</style>
<h1>Welche ROMs brauche ich?</h1><p>Uni-Language Ascendant 1.4.0 · Gen1, Gen2 und Gen3</p>
<aside>Für eine Edition genügt <b>ein Paar</b>: die englische US-Basis und die gewünschte Sprach-ROM. Du brauchst nur die ROMs deiner gewünschten Edition und Sprachen. Englisch allein benötigt nur die Basis-ROM. Beschaffe die passende Edition und erstelle einen Dump deines Moduls; prüfe anschließend dessen SHA-1. Der Dateiname identifiziert keine Revision.</aside>
<p><b>PT-BR ist eine Fanübersetzung.</b> Dafür benötigst du einen eigenen Dump der passenden Patch-Basis und den zugehörigen Übersetzungspatch. Die Prüfsumme der fertigen Sprach-ROM muss dem Eintrag unten entsprechen. <a href="PT-BR.html">Patchquellen und die abweichenden Basisrevisionen von Feuerrot/Blattgrün</a> sind im PT-BR-Bericht erklärt.</p>
<p>Diese Liste enthält die konkret freigegebenen Versionen. Revision 1 entspricht Version 1.1. Weitere vom Recompiler akzeptierte Revisionen werden nicht automatisch von der Sprachmod unterstützt.</p>
<label>Edition suchen <input id="filter" type="search" placeholder="z. B. Saphir oder Gen 2"></label>
<table><thead><tr><th>Edition</th><th>US-Basisspiel · SHA-1</th><th>Zusätzliche Sprach-ROM · SHA-1</th></tr></thead><tbody>'''+''.join(parts)+'''</tbody></table>
<h2>Version kontrollieren</h2><p>macOS/Linux: <code>shasum -a 1 "/Pfad/zur/ROM.gba"</code>Windows PowerShell: <code>Get-FileHash "C:\\Pfad\\zur\\ROM.gba" -Algorithm SHA1</code></p>
<h2>Vorhandene Dateien</h2><p>Die bereitgestellten Gen1-/Gen2-ROMs und Blattgrün, Rubin, Smaragd stimmen mit diesen Profilen überein. Für Feuerrot Deutsch wurde ein SHA-1-identischer Referenz-Build getestet; eine eigene deutsche ROM ist weiterhin für den Import erforderlich.</p>
<p>Die vorhandene Saphir-Datei <code>99f7ad71de5de97ca643f2c4123a77ee79af8e80</code>weicht im Bereich 0x5BFE5C bis 0x67FE5B vom geprüften Dump ab (781.268 abweichende Bytes). Sie wird nicht als regulärer Import akzeptiert. Erwartet wird die oben genannte SHA-1 7e6e034f… . Die Originaldatei wurde nicht geändert.</p>
<p>SHA-1-Referenz für Saphir: <a href="https://github.com/TASEmulators/BizHawk/blob/master/Assets/gamedb/gamedb_gba.txt">BizHawk-Spieldatenbank</a>. Feuerrot/Saphir wurden zusätzlich gegen lokale Decompilation-Builds geprüft.</p>
<h2>Emerald / Smaragd ist nicht mehrsprachig</h2><p>Die englische USA/Europe-ROM (BPEE) enthält keine vollständigen weiteren Sprachfassungen. Deutsch (BPED) ist eine separate ROM. Die zehn Menüsprachen der Mod sind unabhängig von den Spielprofilen: EN/DE/PT-BR für alle elf Editionen. KO für Gold/Silber und JA für Kristall sind enthalten; native ROM-Texte und eigene US-Kompatibilitätsübersetzungen sind in ASIAN-PREVIEW.md getrennt dokumentiert. Zusätzlich ES für Rot/Gelb; FR/IT/ES für Gold und Smaragd; FR/ES für Silber; IT/ES für Kristall und Feuerrot; FR/ES für Blattgrün. Aktuelle Integrationstests: MERGE-QA.json; historische europäische Tests: EUROPE-PREVIEW.md. PT-BR nutzt geprüfte Fanübersetzungsquellen und eigene Ergänzungen der Mod; siehe <a href="PT-BR.html">PT-BR-Prüfbericht</a>.</p>
<h2>Weitere Sprachen und Generationen</h2><p><a href="Weitere-Sprachen.html">Zusätzliche Sprach-ROMs: Entwicklungsbedarf, Versionen und SHA-1</a>. Diese zusätzlichen Profile sind noch nicht unterstützt oder getestet.</p><p>Die Auswahl liest die registrierten Sprachprofile. Weitere Sprachen benötigen ein geprüftes Text-/Grafikprofil und einen passenden Laufzeitadapter. Eine zusätzliche Generation benötigt außerdem eine Spielengine im Recompiler. Aktuell sind Gen1 bis Gen3 freigegeben.</p>
<script>document.querySelector('#filter').addEventListener('input',e=>{let q=e.target.value.toLowerCase().replaceAll(' ','');document.querySelectorAll('tbody tr').forEach(r=>r.hidden=!r.textContent.toLowerCase().replaceAll(' ','').includes(q))})</script></html>'''
(r/'mod/ROM-Liste.html').write_text(body.replace('1.4.0',m['version']).replace('__VERSION__',m['version']))
print('ROM_CATALOG_OK',len(rows),'editions',sum(len(x['sources']) for x in rows),'language profiles')
